<script setup>
import { useOpenSong } from '../../api/openSong.js'
const openSong = useOpenSong()
import { ref, onMounted, onUnmounted, computed, watch } from 'vue'
import levelCard from '../../components/cards/levelCard.vue'
import { getLevelGroups } from '../../api/levels.js'
import { setAnchorNav, clearAnchorNav } from '../../composables/useAnchorNav.js'

const levelList = ref(null)

onMounted(async () => {
  try {
    const data = await getLevelGroups()
    levelList.value = data
  } catch (error) {
    console.error(error)
  }
})

const props = defineProps({
  columns: {
    type: Number,
    default: 6
  },
  gap: {
    type: Number,
    default: 0.20
  },
  gridWidth: {
    type: [Number, String],
    default: '100%'
  }
})

const containerStyle = computed(() => {
  return {
    width: typeof props.gridWidth === 'number' ? `${props.gridWidth}px` : props.gridWidth,
    margin: '0 auto',
    boxSizing: 'border-box'
  }
})

const getGridStyle = () => {
  return {
    '--column-count': props.columns,
    '--gap-rem': `${props.gap}rem`
  }
}

const sortedCardList = computed(() => {
  if (!levelList.value) return []
  const entries = Object.entries(levelList.value)
  const sortedEntries = entries.sort((a, b) => Number(b[0]) - Number(a[0]))
  return sortedEntries.map(([key, value]) => ({ key, value }))
})

// 每个定数段登记成一个锚点，侧栏的「本页目录」可以直接跳段
watch(
  sortedCardList,
  (list) => {
    if (!list.length) {
      clearAnchorNav()
      return
    }
    // 一级是整数定数（18 / 17 …），二级是它下面各档小数定数
    const parents = []
    const byInt = new Map()
    list.forEach((group) => {
      const level = Number(group.key)
      const intPart = Math.floor(level)
      let parent = byInt.get(intPart)
      if (!parent) {
        parent = { id: `level-${group.key}`, label: String(intPart), icon: 'format-list-numbered', children: [] }
        byInt.set(intPart, parent)
        parents.push(parent)
      }
      parent.children.push({ id: `level-${group.key}`, label: level.toFixed(1) })
    })
    setAnchorNav(parents)
  },
  { immediate: true }
)

onUnmounted(clearAnchorNav)

const totalCharts = computed(() =>
  sortedCardList.value.reduce((sum, group) => sum + group.value.length, 0)
)
</script>

<template>
  <div class="dt-page">

    <div class="card-container" :style="containerStyle">
      <section v-for="({ key: groupKey, value: cardGroup }) in sortedCardList" :id="`level-${groupKey}`" :key="groupKey" class="card-group">
        <div class="dt-section__head">
          <h2 class="group-title dt-title-bar">{{ Number(groupKey).toFixed(1) }}</h2>
        </div>
        <div class="level-row">
          <div class="card-grid" :style="getGridStyle()">
            <levelCard
              v-for="(item, idx) in cardGroup"
              :key="idx"
              :chart-info="item" @click="openSong(item[0])"
            />
          </div>
        </div>
      </section>
    </div>
  </div>
</template>

