/**
 * 「点卡片进详情」的共用跳转：曲目键名 → /single/<曲目键名>。
 * 各列表页都用这个，避免每页各写一份 useRouter + push。
 */
import { useRouter } from 'vue-router'

export function useOpenSong() {
  const router = useRouter()
  return (songId) => {
    if (!songId) return
    router.push({ name: 'singleMain', params: { songName: songId } })
  }
}
