/**
 * 定数列表页与 B30 页的取数逻辑。
 * 两者都基于 infos.json 里的难度等级，共用一次网络请求（见 api/infos.js）。
 */
import { loadInfos } from './infos.js'
import { difColor, chartCover, formatRks } from './common.js'

/**
 * 从 infos.json 里收集「已显示歌曲」的难度条目。
 * @returns {Array} [曲目键名, 定数, 难度] 或 [曲目键名, 定数, 难度, 曲名]
 */
function collectDifficulties(jsonData, difficultyTypes, withName = false) {
  const list = []

  for (const [levelId, levelInfo] of Object.entries(jsonData)) {
    if (!levelInfo.name) continue
    if (!levelInfo.display) continue

    for (const difType of difficultyTypes) {
      const lvl = levelInfo[difType]?.lvl
      if (!lvl || lvl.trim() === '') continue

      const levelValue = parseFloat(lvl)
      if (isNaN(levelValue)) continue

      list.push(
        withName
          ? [levelId, levelValue, difType, levelInfo.name]
          : [levelId, levelValue, difType]
      )
    }
  }

  return list
}

/** 定数列表页：按定数分组；每张卡是 [曲目键名, 定数, 曲绘, 难度名, 难度色, 曲名] */
export async function getLevelGroups() {
  try {
    const jsonData = await loadInfos()
    const dif = collectDifficulties(jsonData, ['EZ', 'HD', 'IN', 'AT'])

    for (const item of dif) {
      item[1] = Math.round(item[1] * 10) / 10
      const originalDifType = item[2]
      // 个别曲目每档难度用不同的曲绘
      item[2] = chartCover(item[0], originalDifType)
      item.push(originalDifType)
      item.push(difColor(originalDifType))
      // 卡片上不画曲名，这个位置只给不可见的搜索文本用
      item.push(jsonData[item[0]]?.name || item[0])
    }

    const setL = {}
    for (const subList of dif) {
      const key = subList[1]
      if (!setL[key]) {
        setL[key] = []
      }
      setL[key].push(subList)
    }

    const sSetL = {}
    for (const [key, valueList] of Object.entries(setL)) {
      sSetL[key] = valueList.sort((a, b) => a[0].localeCompare(b[0]))
    }

    return sSetL
  } catch (error) {
    console.error('获取数据失败：', error)
    console.error('实际请求的JSON文件路径：/files/infos/infos.json')
    return {}
  }
}

/** B30 页：取 IN/AT 定数最高的 30 条（前 3 条为 P1~P3）与 RKS */
export async function getB30() {
  try {
    const jsonData = await loadInfos()
    const dif = collectDifficulties(jsonData, ['IN', 'AT'], true)

    dif.sort((a, b) => b[1] - a[1])

    for (const item of dif) {
      item[1] = Math.round(item[1] * 10) / 10
      const originalDifType = item[2]
      // 个别曲目每档难度用不同的曲绘
      item[2] = chartCover(item[0], originalDifType)
      item.push(originalDifType)
      item.push(difColor(originalDifType))
    }

    const top3Copy = dif.slice(0, 3).map((item) => [...item])

    for (let i = 0; i < dif.length; i++) {
      const rank = i + 1
      if (rank <= 27) {
        dif[i].push(`[B${rank}]`)
        dif[i].push(false)
      }
    }

    for (let i = 0; i < top3Copy.length; i++) {
      const rank = i + 1
      top3Copy[i].push(`[P${rank}]`)
      top3Copy[i].push(true)
    }

    const finalDif = [...top3Copy, ...dif].slice(0, 30)
    const b30Level = finalDif.map((item) => item[1])
    const rks = b30Level.reduce((sum, val) => sum + val, 0) / 30
    const nRks = rks.toFixed(2)
    const dRks = formatRks(rks)

    return [finalDif, [nRks, dRks]]
  } catch (error) {
    console.error('获取数据失败：', error)
    console.error('实际请求的JSON文件路径：/files/infos/infos.json')
    return {}
  }
}
